; poll.asm -- chapter 27: 5S from the read that found F
; generated by gen27.py
        INCLUDE "msx.inc"
        OUTPUT "poll.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; WHERE IT BREAKS. Six figures on lines 88 to 103. Every frame the program
; waits for F, and if the status that ended the wait says 5S, a sprite was
; left out, it sends the table turned by 2 entries more; else as before.
copy    EQU $C400               ; the entries twice ($D0 sent once)
log     EQU $C600               ; the status that ended each wait, and the OR
next    EQU VARS                ; where the next two go
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 160
        otir
        ld hl, atts             ; the copy: the six entries twice
        ld de, copy
        ld bc, 24
        ldir
        ld hl, atts
        ld bc, 24
        ldir
        ld hl, log
        ld (next), hl
        VRAM_WRITE $1B00        ; the attributes
        ld hl, atts
        ld c, VDP_DATA
        ld b, 25
        otir
        VDP_REG 1, $C2          ; the display on, sprites of 16 x 16
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        call frame              ; to the end of this paper: the next wait is whole
        ld e, 48
        ld d, 0                 ; k, times 4: the first entry sent
frame6: ld b, 0                 ; nothing seen yet
wait:   in a, (VDP_CTRL)        ; 12  the status
        ld c, a                 ;  5
        or b                    ;  5  every read's bits, kept in B
        ld b, a                 ;  5
        bit 7, c                ; 10  F: the paper has ended
        jr z, wait              ; 13, or 8
        ld a, c                 ;  5  the status that ended the wait
m0:     ld hl, (next)           ; the status, and the OR of the wait, kept
        ld (hl), c
        inc hl
        ld (hl), b
        inc hl
        ld (next), hl
        and $40                 ; 5S?
        jr z, same
        ld a, d                 ; a sprite left out: k + 2, round 6
        add a, 8
        cp 24
        jr c, inside
        sub 24
inside: ld d, a
same:   VRAM_WRITE $1B00        ; the copy from entry k
        ld hl, copy
        ld b, 0
        ld c, d
        add hl, bc
        ld c, VDP_DATA
        ld b, 24
        otir
m1:     dec e
        jr nz, frame6
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
atts:
        db $57, $10, $00, $01
        db $57, $38, $00, $01
        db $57, $60, $00, $01
        db $57, $88, $00, $01
        db $57, $B0, $00, $01
        db $57, $D8, $00, $01
        db $D0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
